  press(Key::Okay);             // List (fresh: the retention probe dropped it)
  commit("2");
  press(Key::Okay);  // Params
  type("5");
  press(Key::Execute);  // N = 5
  type("0.5");
  press(Key::Execute);  // p = 0.5 (selection advances to Execute)
  CalculatorApp::press(Key::Okay);  // Execute starts the job (no drain)
